arguments.file_text:
@page "/track/{TrackingNumber?}"

@inject IShipmentService ShipmentService
@inject NavigationManager Navigation

<PageTitle>Track Shipment</PageTitle>

<h1>Track Shipment</h1>

<div class="row mb-4">
    <div class="col-md-6">
        <div class="input-group">
            <input type="text" class="form-control" placeholder="Enter tracking number"
                   @bind="searchNumber" @bind:event="oninput"
                   @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary" @onclick="Search" disabled="@string.IsNullOrWhiteSpace(searchNumber)">
                Track
            </button>
        </div>
    </div>
</div>

@if (loading)
{
    <p><em>Loading...</em></p>
}
else if (notFound)
{
    <div class="alert alert-warning">No shipment found with tracking number <strong>@TrackingNumber</strong>.</div>
}
else if (shipment is not null)
{
    <div class="card">
        <div class="card-header">
            <strong>@shipment.TrackingNumber</strong>
            <span class="badge bg-info ms-2">@shipment.Status</span>
        </div>
        <div class="card-body">
            <dl class="row mb-0">
                <dt class="col-sm-3">Origin</dt>
                <dd class="col-sm-9">@shipment.Origin</dd>

                <dt class="col-sm-3">Destination</dt>
                <dd class="col-sm-9">@shipment.Destination</dd>

                <dt class="col-sm-3">Recipient</dt>
                <dd class="col-sm-9">@(shipment.RecipientName ?? "—")</dd>

                <dt class="col-sm-3">Shipped Date</dt>
                <dd class="col-sm-9">@shipment.ShippedDate.ToString("MMM dd, yyyy")</dd>

                <dt class="col-sm-3">Estimated Delivery</dt>
                <dd class="col-sm-9">@(shipment.EstimatedDelivery?.ToString("MMM dd, yyyy") ?? "—")</dd>

                <dt class="col-sm-3">Actual Delivery</dt>
                <dd class="col-sm-9">@(shipment.ActualDelivery?.ToString("MMM dd, yyyy") ?? "—")</dd>
            </dl>
        </div>
    </div>
}

@code {
    [Parameter] public string? TrackingNumber { get; set; }

    private ShipmentDto? shipment;
    private bool loading;
    private bool notFound;
    private string searchNumber = string.Empty;

    protected override async Task OnParametersSetAsync()
    {
        if (!string.IsNullOrWhiteSpace(TrackingNumber))
        {
            searchNumber = TrackingNumber;
            await LoadShipment();
        }
    }

    private async Task LoadShipment()
    {
